// the picture made, by its file's URL where OAIY's engine gave one (its bytes otherwise): what is passed on,
// so the steps after it are handed a reference, not the picture
return (made && made.file) || made_image;

// the picture an edit starts from: the one given (a data URL, or a picture of OAIY's engines by its address),
// else the one made (by reference)
const given = String(picture == null ? '' : picture).trim();
return given || made_ref;

// what the reviewer is asked: the request the final picture must meet (an edit's changes are what was asked for)
const idea = String(prompt == null ? '' : prompt).trim();
const change = String(edit == null ? '' : edit).trim();
const given = !!String(picture == null ? '' : picture).trim();
if (!change) {
  if (given) {
    return idea ? `The person gave this picture and says it should show: ${idea}\n\nCheck the picture against that.`
      : 'The person gave this picture. Check it for its text (exactly as written), its colours, objects and composition.';
  }
  return `The person asked for: ${idea}\n\nThe caption the picture was made from: ${caption}\n\nCheck the picture against what the person asked for.`;
}
const first = given
  ? (idea ? `The person gave a picture (the second one), which they describe as: ${idea}` : 'The person gave a picture (the second one).')
  : `The person first asked for: ${idea}`;
return `${first}\n\nThen they asked for this change, which the final picture must show: ${change}\n\n` +
  'The change is correct, not an issue: where it replaces something from the first request (a colour, a word), the final ' +
  'picture must have the new one. Everything the change does not mention must look as it did before the edit (the second picture).';

data.systemPrompt:
You check a generated picture against what was asked, and you are careful and specific. The first picture is the final one; a second picture, where there is one, is how it looked before it was edited. Reply with JSON alone, no prose and no code fence, in exactly this shape:
{"verdict": "pass" or "needs_attention", "confidence": a number from 0 to 1, "text": {"requested": [each word or phrase the request asks to appear in the picture, exactly as asked, e.g. "GOOD NIGHT"], "found": [each word or phrase you can read in the final picture, letter by letter, e.g. "GOOD NIGHT"], "exact": true, false or null, "unintended": [text that appears but was not asked for]}, "colours": {"requested": [colours asked for], "matches": true, false or null, "note": "..."}, "objects": {"missing": [...], "extra": [...]}, "composition": "one sentence", "edit": {"applied": true, false or null, "unaffected_preserved": true, false or null, "note": "..."}, "issues": ["each concrete problem"], "uncertain": ["what you could not tell for sure"]}
Judge the final picture against the request as you are given it: when a change was asked for, the picture must show the change, and what the change replaced is no longer asked for. The text lists hold the words alone, never a description of the picture. Use null where the request says nothing about it, and for edit when there was no edit. Read lettering letter by letter before you call it exact. A verdict of pass needs no issues that matter.

