// The flow's answer: references to the pictures (their files' URLs, never the pictures themselves), what made
// them, and the review's findings (read from its reply; kept as text where it is not JSON).
const parse = (reply) => {
  if (reply == null) return null;
  const text = String(reply).trim().replace(/^```(?:json)?\s*/i, '').replace(/```$/, '').trim();
  const at = text.indexOf('{'), end = text.lastIndexOf('}');
  try { return JSON.parse(at >= 0 && end > at ? text.slice(at, end + 1) : text); } catch { return { unparsed: text }; }
};
const final = edited || made;
return {
  image: final ? final.file : null,
  original: made ? made.file : null,
  edited: !!edited,
  given: !!String(picture == null ? '' : picture).trim(),
  prompt,
  caption,
  edit: edited ? edit : null,
  review: parse(review),
  pictures: { made, edited: edited || null },
};
